enum TiffFieldType {
  byte=1
  ascii=2
  short=3
  long=4
  rational=5
  sByte=6
  undefined=7
  sShort=8
  sLong=9
  sRational=10
  float=11
  double=12
}
record TiffStorage {
  kind Ref(TiffStorageKind)
  offsetsKind Ref(TiffFieldType)
  byteCountsKind Ref(TiffFieldType)
  chunks array Ref(TiffChunk)
}
enum TiffStorageKind {
  none=0
  strips=1
  tiles=2
}
